-- rule unknown_procure_code (row): parameterized; p1 text
SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) OR EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."child_id" = t."part_id" AND e."parent_id" IS NOT NULL)) AND ((t."procure" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."code_value" r WHERE r."code" = t."procure" AND r."code_group" = CAST(:p1 AS text))) OR (t."procure" IS NULL));

-- rule unknown_procure_code: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_unknown_procure_code" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) OR EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."child_id" = t."part_id" AND e."parent_id" IS NOT NULL)) AND ((t."procure" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_rules"."code_value" r WHERE r."code" = t."procure" AND r."code_group" = CAST(E'PROCURE' AS text))) OR (t."procure" IS NULL))) r;

-- example unknown_procure_code[0]: parameterized; 21 parameters
WITH "sxc_ex_part"("part_id", "procure") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS text)), (CAST(:p3 AS text), CAST(:p4 AS text)), (CAST(:p5 AS text), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS text)), (CAST(:p9 AS text), CAST(:p10 AS text))), "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p11 AS text), CAST(:p12 AS text)), (CAST(:p13 AS text), CAST(:p14 AS text)), (CAST(:p15 AS text), CAST(:p16 AS text))), "sxc_ex_code_value"("code", "code_group") AS (VALUES (CAST(:p17 AS text), CAST(:p18 AS text)), (CAST(:p19 AS text), CAST(:p20 AS text))) SELECT * FROM (SELECT t."part_id" FROM "sxc_ex_part" t WHERE (EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL) OR EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e WHERE e."child_id" = t."part_id" AND e."parent_id" IS NOT NULL)) AND ((t."procure" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "sxc_ex_code_value" r WHERE r."code" = t."procure" AND r."code_group" = CAST(:p21 AS text))) OR (t."procure" IS NULL))) r;
